                    {newBKPhoto?"Changer la photo":"📷 Ajouter un logo"}
                    <input type="file" accept="image/*" style={{display:"none"}} onChange={e=>{
                      const f=e.target.files[0];
                      if(!f)return;
                      const r=new FileReader();
                      r.onload=ev=>setNewBKPhoto(ev.target.result);
                      r.readAsDataURL(f);
                    }}/>
